-- ── Schema ───────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.editorial_brands (
  editorial_title  TEXT NOT NULL,
  brand_id         TEXT NOT NULL REFERENCES public.brands(brand_id) ON DELETE CASCADE,
  role             TEXT NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (editorial_title, brand_id, role)
);

CREATE INDEX IF NOT EXISTS editorial_brands_brand_id_idx ON public.editorial_brands(brand_id);
CREATE INDEX IF NOT EXISTS editorial_brands_editorial_title_idx ON public.editorial_brands(editorial_title);

-- RLS: public read (used by editorial+brand pages), service-role write only
ALTER TABLE public.editorial_brands ENABLE ROW LEVEL SECURITY;
CREATE POLICY editorial_brands_public_read ON public.editorial_brands
  FOR SELECT USING (true);
CREATE POLICY editorial_brands_service_write ON public.editorial_brands
  FOR ALL TO service_role USING (true) WITH CHECK (true);

